5	import { MenuItem } from "@/components/menu-item";
6	import { ScrollArea } from "@/components/scroll-area";
7	import { Tooltip } from "@/components/tooltip";
8	
9	import { TicketCard } from "./ticket-card";
10	
11	type TicketCardProps = ComponentProps<typeof TicketCard>;
12	
13	export interface TicketBoardItem {
14	  id: string;
15	  cardProps: Omit<TicketCardProps, "draggable" | "onDragStart" | "onDragEnd" | "isSelected">;
16	}
17	
18	export interface TicketBoardColumnAction {
19	  id: string;
20	  label: string;
21	  icon: ComponentType<{ size?: number | string }>;
22	}
23	
24	export interface TicketBoardGroup {
25	  key: string;
26	  label: string;
27	  items: TicketBoardItem[];
28	}
29	
30	export interface TicketBoardColumn {
31	  id: string;
32	  label: string;
33	  color?: string;
34	  items: TicketBoardItem[];
35	  groups?: TicketBoardGroup[];
36	  canDragIn: boolean;
37	  canDragOut: boolean;
38	  canCreate: boolean;
39	  actions: TicketBoardColumnAction[];
40	}
41	
42	interface TicketBoardProps {
43	  columns: TicketBoardColumn[];
44	  selectedItemId?: string | null;
45	  onMoveItem?: (itemId: string, targetColumnId: string) => void;
46	  onMoveToGroup?: (itemId: string, targetGroupKey: string) => void;
47	  onCreateStart?: (columnId: string) => void;
48	  onColumnAction?: (columnId: string, actionId: string) => Promise<void> | void;
49	}
50	
51	export const TicketBoard = (props: TicketBoardProps) => {
52	  const { columns, selectedItemId = null, onMoveItem, onMoveToGroup, onCreateStart, onColumnAction } = props;
53	
54	  const [activeColumn, setActiveColumn] = useState<string | null>(null);
55	  const [activeGroup, setActiveGroup] = useState<string | null>(null);
56	
57	  const handleDragStart = (itemId: string) => (event: DragEvent<HTMLDivElement>) => {
58	    event.dataTransfer.setData("text/plain", itemId);
59	    event.dataTransfer.effectAllowed = "move";
60	  };
61	
62	  const handleDragEnd = () => {
63	    setActiveColumn(null);
64	    setActiveGroup(null);
65	  };
66	
67	  const handleDragOver = (columnId: string) => (event: DragEvent<HTMLDivElement>) => {
68	    event.preventDefault();
69	    event.dataTransfer.dropEffect = "move";
70	    setActiveColumn(columnId);
71	  };
72	
73	  const handleDragLeave = (event: DragEvent<HTMLDivElement>) => {
74	    if (event.currentTarget.contains(event.relatedTarget as Node)) return;
75	    setActiveColumn(null);
76	  };
77	
78	  const handleDrop = (columnId: string) => (event: DragEvent<HTMLDivElement>) => {
79	    event.preventDefault();
80	    setActiveColumn(null);
81	
82	    const itemId = event.dataTransfer.getData("text/plain");
83	    if (!itemId) return;
84	
85	    onMoveItem?.(itemId, columnId);
86	  };
87	
88	  return (
89	    <ScrollArea
90	      height="100%"
91	      showHorizontalScrollbar
92	      showVerticalScrollbar={false}
93	      contentProps={{ display: "flex", alignItems: "stretch", gap: "0", pb: "2xs", minH: "100%" }}
94	    >
95	      {columns.map((column) => (
96	        <Stack
97	          key={column.id}
98	          data-testid={`board-column-${column.id}`}
99	          gap="xs"
100	          _notFirst={{ borderLeft: "1px solid", borderColor: "border.muted" }}
101	          background={activeColumn === column.id ? "bg.subtle" : "bg"}
102	          transition="background 150ms ease"
103	          height="100%"
104	          minH="240px"
105	          overflow="hidden"
106	          minW="260px"
107	          flex="1 0 260px"
108	          onDragOver={column.canDragIn ? handleDragOver(column.id) : undefined}
109	          onDragLeave={column.canDragIn ? handleDragLeave : undefined}
110	          onDrop={column.canDragIn ? handleDrop(column.id) : undefined}
111	        >
112	          <ColumnHeader column={column} onCreateStart={onCreateStart} onColumnAction={onColumnAction} />
113	
114	          <ScrollArea
115	            flex="1"
116	            minH="0"
117	            verticalScrollbarProps={{ margin: "0" }}
118	            contentProps={{
119	              spaceY: "sm",
120	              ps: "xs",
121	              pe: "xs",
122	            }}
123	          >
124	            {column.groups && column.groups.length > 0
125	              ? column.groups.map((group) => {
126	                  const groupId = `${column.id}::${group.key}`;
127	                  return (
128	                    <GroupSection
129	                      key={group.key}
130	                      group={group}
131	                      selectedItemId={selectedItemId}
132	                      canDragIn={column.canDragIn}
133	                      canDragOut={column.canDragOut}
134	                      isDropTarget={activeGroup === groupId}
135	                      onDragStart={handleDragStart}
136	                      onDragEnd={handleDragEnd}
137	                      onGroupDragOver={(event) => {
138	                        event.preventDefault();
139	                        event.stopPropagation();
140	                        event.dataTransfer.dropEffect = "move";
141	                        setActiveGroup(groupId);
142	                        setActiveColumn(null);
143	                      }}
144	                      onGroupDragLeave={(event) => {
145	                        if (event.currentTarget.contains(event.relatedTarget as Node)) return;
146	                        setActiveGroup(null);
147	                      }}
148	                      onGroupDrop={(event) => {
149	                        event.preventDefault();
150	                        event.stopPropagation();
151	                        setActiveGroup(null);
152	                        setActiveColumn(null);
153	                        const itemId = event.dataTransfer.getData("text/plain");
154	                        if (!itemId) return;
155	                        onMoveItem?.(itemId, column.id);
156	                        onMoveToGroup?.(itemId, group.key);
157	                      }}
158	                    />
159	                  );
160	                })
161	              : column.items.map((item) => (
162	                  <TicketCard
163	                    key={item.id}
164	                    {...item.cardProps}
165	                    isSelected={item.id === selectedItemId}
166	                    draggable={column.canDragOut}
167	                    onDragStart={column.canDragOut ? handleDragStart(item.id) : undefined}
168	                    onDragEnd={column.canDragOut ? handleDragEnd : undefined}
169	                  />
170	                ))}
171	          </ScrollArea>
172	        </Stack>
173	      ))}
174	    </ScrollArea>
175	  );
176	};
177	
178	interface ColumnHeaderProps {
179	  column: TicketBoardColumn;
180	  onCreateStart?: (columnId: string) => void;
181	  onColumnAction?: (columnId: string, actionId: string) => Promise<void> | void;
182	}
183	
184	interface GroupSectionProps {
185	  group: TicketBoardGroup;
186	  selectedItemId: string | null;
187	  canDragIn: boolean;
188	  canDragOut: boolean;
189	  isDropTarget: boolean;
190	  onDragStart: (itemId: string) => (event: DragEvent<HTMLDivElement>) => void;
191	  onDragEnd: () => void;
192	  onGroupDragOver: (event: DragEvent<HTMLDivElement>) => void;
193	  onGroupDragLeave: (event: DragEvent<HTMLDivElement>) => void;
194	  onGroupDrop: (event: DragEvent<HTMLDivElement>) => void;
195	}
196	
197	const GroupSection = (props: GroupSectionProps) => {
198	  const {
199	    group,
200	    selectedItemId,
201	    canDragIn,
202	    canDragOut,
203	    isDropTarget,
204	    onDragStart,
205	    onDragEnd,
206	    onGroupDragOver,
207	    onGroupDragLeave,
208	    onGroupDrop,
209	  } = props;
210	  const [expanded, setExpanded] = useState(true);
211	
212	  return (
213	    <Stack
214	      gap="0"
215	      borderRadius="sm"
216	      background={isDropTarget ? "bg.subtle" : "transparent"}
217	      transition="background 150ms ease"
218	      onDragOver={canDragIn ? onGroupDragOver : undefined}
219	      onDragLeave={canDragIn ? onGroupDragLeave : undefined}
220	      onDrop={canDragIn ? onGroupDrop : undefined}
221	    >
222	      <HStack
223	        px="xs"
224	        py="2xs"
225	        gap="2xs"
226	        cursor="pointer"
227	        _hover={{ bg: "bg.hover" }}
228	        borderRadius="sm"
229	        onClick={() => setExpanded((v) => !v)}
230	      >
231	        <Box display="flex" alignItems="center" flexShrink={0}>
232	          <Icon
233	            as={ChevronRight}
234	            boxSize="14px"
235	            color="fg.muted"
236	            transform={expanded ? "rotate(90deg)" : "rotate(0deg)"}
237	            transition="transform 0.15s ease"
238	          />
239	        </Box>
240	        <Text textStyle="label/S/medium" color="fg.muted">
241	          {group.label}
242	        </Text>
243	        <Badge variant="subtle" colorPalette="gray" size="sm">
244	          {group.items.length}
245	        </Badge>
246	      </HStack>
247	      {expanded && (
248	        <Stack gap="sm" pt="xs">
249	          {group.items.map((item) => (
250	            <TicketCard
251	              key={item.id}
252	              {...item.cardProps}
253	              isSelected={item.id === selectedItemId}
254	              draggable={canDragOut}
255	              onDragStart={canDragOut ? onDragStart(item.id) : undefined}
256	              onDragEnd={canDragOut ? onDragEnd : undefined}
257	            />
258	          ))}
259	        </Stack>
260	      )}
261	    </Stack>
262	  );
263	};
264	
265	const ColumnHeader = (props: ColumnHeaderProps) => {
266	  const { column, onCreateStart, onColumnAction } = props;
267	
268	  return (
269	    <HStack padding="xs" gap="xs" alignItems="center">
270	      <Text textStyle="label/L/medium">{column.label}</Text>
271	
272	      <Badge variant="subtle" colorPalette={column.color ?? "gray"}>
273	        {column.items.length}
274	      </Badge>
275	
276	      <Spacer />
277	
278	      {column.canCreate && onCreateStart && (
279	        <Tooltip content="Create new ticket">
280	          <IconButton size="2xs" variant="outline" onClick={() => onCreateStart(column.id)} aria-label="Create ticket">
281	            <Icon as={Plus} boxSize="12px" />
282	          </IconButton>
283	        </Tooltip>
284	      )}
285	
286	      {column.actions.length > 0 && (
287	        <Menu.Root>
288	          <Menu.Trigger asChild>
289	            <IconButton size="2xs" variant="ghost" aria-label={`Column actions for ${column.label}`}>
290	              <Icon as={MoreHorizontal} boxSize="12px" />
291	            </IconButton>
292	          </Menu.Trigger>
293	          <Menu.Positioner>
294	            <Menu.Content minW="180px" bg="bg">
295	              {column.actions.map((action) => (
296	                <MenuItem
297	                  key={action.id}
298	                  primaryLabel={action.label}
299	                  leftIcon={action.icon}
300	                  onClick={() => onColumnAction?.(column.id, action.id)}
301	                />
302	              ))}
303	            </Menu.Content>
304	          </Menu.Positioner>
305	        </Menu.Root>
306	      )}
307	    </HStack>
308	  );
309	};
